{"id": "stream_buffer_v1", "synthetic_mutation_challenge": true, "module": "stream_buffer", "description": "A synchronous, non-bypassing, lossless ready/valid queue carrying DATA_WIDTH payload bits, LAST and USER. Capacity is 2**ADDR_WIDTH words.", "reset": "Active-high synchronous reset flushes all accepted but unconsumed words at each rising edge. While reset is asserted, s_ready and m_valid are zero. The first four directed cycles assert reset.", "handshake": "Outside reset a transfer occurs on a rising edge when valid and ready are both high. The source must hold valid and its data/sidebands while stalled, unless reset is asserted. The receiver may stop for any number of cycles.", "availability": "m_valid is high exactly when buffered words exist. The head data and sidebands remain stable while stalled. No direct input-to-output bypass is allowed.", "ready": "s_ready must be high exactly when reset is low and either there is unused capacity or an existing head word will be consumed on this edge. Full-capacity simultaneous dequeue/enqueue must be supported.", "ordering": "Each accepted word, including LAST and USER, appears once and in order unless flushed by reset. New traffic must work after reset; tying off ready or valid cannot satisfy the contract.", "parameters": "Directed checks use DATA_WIDTH=8 and ADDR_WIDTH in {1,2,3}; formal checks will use listed fixed profiles only. This is not an all-parameter or unbounded proof.", "reference_rtl_used_for_scoring": false}
Candidate RTL:
// SPDX-License-Identifier: MIT
module stream_buffer #(
    parameter ADDR_WIDTH = 2,
    parameter DATA_WIDTH = 8
)(
    input wire clk,
    input wire rst,
    input wire [DATA_WIDTH-1:0] s_data,
    input wire s_valid,
    output wire s_ready,
    input wire s_last,
    input wire s_user,
    output wire [DATA_WIDTH-1:0] m_data,
    output wire m_valid,
    input wire m_ready,
    output wire m_last,
    output wire m_user
);

localparam DEPTH = 1 << ADDR_WIDTH;
reg [DATA_WIDTH+1:0] mem [0:DEPTH-1];
reg [ADDR_WIDTH-1:0] wr_ptr = 0;
reg [ADDR_WIDTH-1:0] rd_ptr = 0;
reg [ADDR_WIDTH:0] count = 0;

assign m_valid = !rst && (count != 0);
assign s_ready = !rst && ((count < DEPTH) || (m_ready && m_valid));
assign {m_last, m_user, m_data} = mem[rd_ptr];
wire push = s_valid && s_ready;
wire pop = m_valid && m_ready;

always @(posedge clk) begin
    if (rst) begin
        wr_ptr <= wr_ptr;
        rd_ptr <= 0;
        count <= 0;
    end else begin
        if (push) begin
            mem[wr_ptr] <= {s_last, s_user, s_data};
        end
        if (push) wr_ptr <= wr_ptr + 1'b1;
        if (pop) rd_ptr <= rd_ptr + 1'b1;
        case ({push, pop})
            2'b10: count <= count + 1'b1;
            2'b01: count <= count - 1'b1;
            default: count <= count;
        endcase
    end
end
endmodule

{"decision": "repair", "rtl": "// SPDX-License-Identifier: MIT
module stream_buffer #(
    ADDR_WIDTH = 2,
    DATA_WIDTH = 8
)(
    input clk,
    input rst,
    input [DATA_WIDTH-1:0] s_data,
    input s_valid,
    output s_ready,
    input s_last,
    input s_user,
    output [DATA_WIDTH-1:0] m_data,
    output m_valid,
    input m_ready,
    output m_last,
    output m_user
);

reg [DATA_WIDTH+1:0] mem [0:(1<<ADDR_WIDTH)-1];
reg [ADDR_WIDTH-1:0] wr_ptr = 0;
reg [ADDR_WIDTH-1:0] rd_ptr = 0;
reg [ADDR_WIDTH:0] count = 0;

wire push = s_valid && s_ready;
wire pop = m_valid && m_ready;

assign m_valid = !rst && (count != 0);
assign s_ready = !rst && ((count < (1<<ADDR_WIDTH)) || (m_ready && m_valid));
assign {m_last, m_user, m_data} = mem[rd_ptr];

always @(posedge clk) begin
    if (rst) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        count <= 0;
    end else begin
        if (push)
            mem[wr_ptr] <= {s_last, s_user, s_data};
        if (push)
            wr_ptr <= wr_ptr + 1;
        if (pop)
            rd_ptr <= rd_ptr + 1;
        case ({push, pop})
            2'b10: count <= count + 1;
            2'b01: count <= count - 1;
            default: count <= count;
        endcase
    end
end
endmodule", "explanation": "The candidate RTL contained syntax errors incompatible with Verilog 2001 (parameter keyword, localparam, wire in port declarations) and a functional bug where the write pointer was not reset during active-high synchronous reset, causing data misalignment after reset. The repaired version uses standard Verilog 2001 syntax, resets wr_ptr to 0, and maintains all required handshake, availability, ready, and ordering properties."}
